package com.example.fanlauncher
import android.content.Context
import android.graphics.*
import android.view.MotionEvent
import android.view.View
import kotlin.math.*
class FanLauncherView(context:Context,private val settings:FanSettings):View(context){
 var tier1Items:List<FanItem> = emptyList();var tier2Items:List<FanItem> = emptyList();var onItemSelected:((FanItem)->Unit)?=null;var onActionSelected:((FanAction)->Unit)?=null
 private val density=resources.displayMetrics.density;private val sweepTotal=settings.fanSweepDeg.toFloat();private val startAngle=if(settings.edge==EdgeSide.RIGHT)180f else 270f
 private val tier1Radius=settings.fanRadiusDp*density;private val tier2Radius=tier1Radius*1.62f;private val actionRadius=min(70f*density,tier1Radius*.30f);private val iconSize=46f*density
 private var vertexX=0f;private var vertexY=0f;private var selectedTier=0;private var selectedIndex=-1;private var selectedAction:FanAction?=null
 override fun onSizeChanged(w:Int,h:Int,ow:Int,oh:Int){vertexX=if(settings.edge==EdgeSide.RIGHT)w.toFloat()else 0f;vertexY=h/2f}
 fun setVertexY(y:Float){vertexY=y.coerceIn(0f,height.toFloat());invalidate()}
 override fun onDraw(c:Canvas){val p=Paint(Paint.ANTI_ALIAS_FLAG);drawTier(c,p,tier1Items,tier1Radius,1,actionRadius);if(settings.tiers==2&&tier2Items.isNotEmpty())drawTier(c,p,tier2Items,tier2Radius,2,tier1Radius);drawCenterActions(c)}
 private fun drawTier(c:Canvas,p:Paint,items:List<FanItem>,radius:Float,tier:Int,inner:Float){if(items.isEmpty())return;val per=sweepTotal/items.size;items.forEachIndexed{i,item->{val start=startAngle+i*per;val selected=selectedTier==tier&&selectedIndex==i;p.color=item.color;p.alpha=if(selected)255 else 185;val path=Path().apply{moveTo(vertexX+inner*cos(Math.toRadians(start.toDouble())).toFloat(),vertexY+inner*sin(Math.toRadians(start.toDouble())).toFloat());arcTo(RectF(vertexX-inner,vertexY-inner,vertexX+inner,vertexY+inner),start,per);lineTo(vertexX+radius*cos(Math.toRadians((start+per).toDouble())).toFloat(),vertexY+radius*sin(Math.toRadians((start+per).toDouble())).toFloat());arcTo(RectF(vertexX-radius,vertexY-radius,vertexX+radius,vertexY+radius),start+per,-per);close()};c.drawPath(path,p);item.icon?.let{icon->val mid=Math.toRadians((start+per/2f).toDouble());val ir=(inner+radius)/2f;val ix=vertexX+ir*cos(mid).toFloat();val iy=vertexY+ir*sin(mid).toFloat();val size=if(selected)iconSize*1.16f else iconSize;val h=size/2f;icon.setBounds((ix-h).toInt(),(iy-h).toInt(),(ix+h).toInt(),(iy+h).toInt());icon.draw(c)}}}}
 private fun drawCenterActions(c:Canvas){val buttons=mutableListOf<FanAction>();if(settings.showScreenshot)buttons+=FanAction.Screenshot;if(settings.showTranslate)buttons+=FanAction.Translate;if(buttons.isEmpty())return;val buttonSize=min(54f*density,actionRadius*.72f);val gap=10f*density;val total=buttons.size*buttonSize+(buttons.size-1)*gap;var left=vertexX-total/2f;buttons.forEach{action->val cx=left+buttonSize/2f;val fill=Paint(Paint.ANTI_ALIAS_FLAG).apply{color=if(action==FanAction.Screenshot)0xFF455A64.toInt()else 0xFF00897B.toInt();alpha=if(selectedAction==action)255 else 220};c.drawCircle(cx,vertexY,buttonSize/2f,fill);val icon=Paint(Paint.ANTI_ALIAS_FLAG).apply{color=Color.WHITE;style=Paint.Style.STROKE;strokeWidth=3f*density;strokeCap=Paint.Cap.ROUND};if(action==FanAction.Screenshot){c.drawRect(cx-buttonSize*.23f,vertexY-buttonSize*.16f,cx+buttonSize*.23f,vertexY+buttonSize*.16f,icon);c.drawCircle(cx,vertexY,buttonSize*.10f,icon)}else{icon.style=Paint.Style.FILL;icon.textSize=buttonSize*.43f;icon.textAlign=Paint.Align.CENTER;c.drawText("文",cx,vertexY+icon.textSize*.34f,icon)};left+=buttonSize+gap}}
 override fun onTouchEvent(e:MotionEvent)=false
 fun updateSelection(rawX:Float,rawY:Float){val loc=IntArray(2);getLocationOnScreen(loc);val x=rawX-loc[0];val y=rawY-loc[1];val dx=x-vertexX;val dy=y-vertexY;val dist=hypot(dx,dy);var angle=Math.toDegrees(atan2(dy.toDouble(),dx.toDouble())).toFloat();if(angle<0)angle+=360f;var n=angle-startAngle;if(n<0)n+=360f;selectedAction=null;selectedTier=0;selectedIndex=-1;if(dist<=actionRadius&&n in 0f..sweepTotal){val actions=mutableListOf<FanAction>();if(settings.showScreenshot)actions+=FanAction.Screenshot;if(settings.showTranslate)actions+=FanAction.Translate;if(actions.isNotEmpty()){val idx=(n/(sweepTotal/actions.size)).toInt().coerceIn(0,actions.size-1);selectedAction=actions[idx]}}else if(n in 0f..sweepTotal){if(dist>=actionRadius&&dist<tier1Radius) {selectedTier=1;selectedIndex=indexFromAngle(n,tier1Items.size)}else if(settings.tiers==2&&dist>=tier1Radius&&dist<tier2Radius){selectedTier=2;selectedIndex=indexFromAngle(n,tier2Items.size)}};invalidate()}
 fun commitSelection(){selectedAction?.let{onActionSelected?.invoke(it)}?:when(selectedTier){1->tier1Items.getOrNull(selectedIndex)?.let{onItemSelected?.invoke(it)};2->tier2Items.getOrNull(selectedIndex)?.let{onItemSelected?.invoke(it)};else->Unit};selectedAction=null;selectedTier=0;selectedIndex=-1}
 private fun indexFromAngle(n:Float,count:Int):Int=if(count==0)-1 else(n/(sweepTotal/count)).toInt().coerceIn(0,count-1)
}
